export default async ({ page }) => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const toBase64 = (input) => {
    if (typeof input === 'string') return input;
    const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
    let binary = '';
    const chunk = 0x8000;
    for (let i = 0; i < bytes.length; i += chunk) {
      binary += String.fromCharCode.apply(null, Array.from(bytes.subarray(i, i + chunk)));
    }
    return btoa(binary);
  };

  const url =
    'http://metabase-szaqo2-metabase-1:3000/public/dashboard/2c3f2f0f-9e45-4af1-a8c2-cdd79105308c?resolution_date=past1weeks&brand_name=&specialist__name=Felipe%20Londono&specialist__name=Andres%20Rodriguez&specialist__name=Daniel%20Ceron&specialist__name=Daniel%20Marin&specialist__name=Ismael%20Marin&specialist__name=Juan%20Trujillo&specialist__name=Juan%20David%20Reyes&specialist__name=Manuel%20Bracho&specialist__name=Ricardo%20Arteta%20Romero&ticket_type=Ad%20Hoc%20Request&ticket_type=Audience&ticket_type=Bulk%20Change&ticket_type=Bonus&ticket_type=Campaign&ticket_type=Content%20Update&ticket_type=EDM&ticket_type=Notification%20Build&ticket_type=Page%20Build&ticket_type=SMS&ticket_type=Sub-Task&ticket_type=Banner%20Build&region=';

  await page.setViewport({ width: 1600, height: 900, deviceScaleFactor: 2 });
  await page.emulateMediaType('screen');
  await page.goto(url, { waitUntil: 'load', timeout: 20000 });
  await page.waitForSelector('[data-testid="dashboard-grid"]', { timeout: 20000 });
  await sleep(8000);

  const heightPx = await page.evaluate(() => {
    document.querySelectorAll(
      'html, body, #root, #Dashboard-Parameters-And-Cards-Container, [data-testid="dashboard-grid"], .Dashboard, .react-grid-layout, [data-testid="dashcard"], .Card, .TableInteractive, .ReactVirtualized__Grid'
    ).forEach((el) => {
      el.style.setProperty('overflow', 'visible', 'important');
      el.style.setProperty('max-height', 'none', 'important');
    });

    document.querySelectorAll('.ReactVirtualized__Grid').forEach((el) => {
      const rows = Number(el.getAttribute('aria-rowcount') || 0);
      if (rows > 0) el.style.setProperty('height', `${rows * 37}px`, 'important');
      else el.style.setProperty('height', 'auto', 'important');
    });

    const grid = document.querySelector('[data-testid="dashboard-grid"]');
    if (grid) grid.style.setProperty('max-width', '1500px', 'important');

    const items = [...document.querySelectorAll('[data-testid="dashboard-grid"] .react-grid-item, [data-testid="dashcard"]')];
    let maxBottom = 0;
    for (const item of items) {
      maxBottom = Math.max(maxBottom, item.offsetTop + item.offsetHeight, item.getBoundingClientRect().bottom + window.scrollY);
    }
    if (grid && maxBottom > 0) {
      const layout = grid.querySelector('.react-grid-layout') || grid;
      layout.style.setProperty('height', `${Math.ceil(maxBottom + 32)}px`, 'important');
    }
    return Math.ceil(
      Math.max(
        maxBottom + 48,
        grid ? grid.scrollHeight : 0,
        grid ? grid.offsetHeight : 0,
        document.documentElement.scrollHeight,
        document.body.scrollHeight
      )
    );
  });

  const viewportHeight = Math.min(Math.max(Math.ceil(heightPx * 1.1) + 48, 900), 8000);
  await page.setViewport({ width: 1600, height: viewportHeight, deviceScaleFactor: 2 });
  await sleep(400);
  const heightIn = Math.min(Math.max(viewportHeight / 96 + 0.5, 12), 90);
  const pdf = await page.pdf({
    printBackground: true,
    width: '18in',
    height: `${heightIn}in`,
    margin: { top: '8px', right: '8px', bottom: '8px', left: '8px' },
    timeout: 20000,
  });
  const image = await page.screenshot({ encoding: 'base64', type: 'png' });
  return { data: { pdf: toBase64(pdf), image, heightPx }, type: 'application/json' };
};

