const lastStart = now.minus({ weeks: 1 }).startOf('week');
const lastEnd = lastStart.endOf('week');
const thisStart = now.startOf('week');
const thisEnd = thisStart.endOf('week');
const fmt = (d) => d.toFormat('dd-MM-yy');
const resolvedRange = `${fmt(lastStart)} - ${fmt(lastEnd)}`;
const expectedRange = `${fmt(thisStart)} - ${fmt(thisEnd)}`;
const resolved = $('Capture resolved dashboard').item.json.data ?? {};
const expected = $json.data ?? {};
if (!resolved.pdf || !resolved.image) throw new Error('Resolved capture missing pdf/image');
if (!expected.pdf || !expected.image) throw new Error('Expected capture missing pdf/image');
const resolvedPdf = await this.helpers.prepareBinaryData(Buffer.from(resolved.pdf, 'base64'), `COL-Team-Resolved (${resolvedRange}).pdf`, 'application/pdf');
const resolvedImage = await this.helpers.prepareBinaryData(Buffer.from(resolved.image, 'base64'), `COL-Team-Resolved (${resolvedRange}).png`, 'image/png');
