const expectedImage = await this.helpers.prepareBinaryData(Buffer.from(expected.image, 'base64'), `COL-Team-Expected-Workload (${expectedRange}).png`, 'image/png');
return { json: { resolvedRange, expectedRange, hidden: expected.hidden, resolvedHeight: resolved.heightPx, expectedHeight: expected.heightPx }, binary: { resolvedPdf, resolvedImage, expectedPdf, expectedImage } };

