export default async ({ page, context }) => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const toBase64 = (input) => {
    if (typeof input === 'string') return input;
    const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
    let binary = '';
    const chunk = 0x8000;
    for (let i = 0; i < bytes.length; i += chunk) {
      binary += String.fromCharCode.apply(null, Array.from(bytes.subarray(i, i + chunk)));
    }
    return btoa(binary);
  };

  const uuid = context && context.uuid;
  if (!uuid) throw new Error('Missing MarkOps public UUID in context.uuid');

  const url =
    'http://metabase-szaqo2-metabase-1:3000/public/dashboard/' +
    uuid +
    '?tab=42-markops&brand=&issue_type=&status=&assignee=Andres%20Rodriguez&assignee=Daniel%20Ceron&assignee=Daniel%20Marin&assignee=Felipe%20Londono&assignee=Ismael%20Marin&assignee=Juan%20David%20Reyes&assignee=Juan%20Trujillo&assignee=Manuel%20Bracho&assignee=Ricardo%20Arteta%20Romero&owner=&created=&updated=&build_due=thisweek&resolved=&vertical=&region=&epic_parent=';

  await page.setViewport({ width: 1600, height: 900, deviceScaleFactor: 2 });
  await page.emulateMediaType('screen');
  await page.goto(url, { waitUntil: 'load', timeout: 20000 });
  await page.waitForSelector('[data-testid="dashboard-grid"]', { timeout: 20000 });
  await sleep(8000);

  const hidden = await page.evaluate(() => {
    const hideEl = (el) => {
      if (!el) return false;
      el.style.setProperty('display', 'none', 'important');
      el.style.setProperty('height', '0', 'important');
      el.style.setProperty('overflow', 'hidden', 'important');
      el.style.setProperty('visibility', 'hidden', 'important');
      return true;
    };

    document.querySelectorAll(
      'html, body, #root, #Dashboard-Parameters-And-Cards-Container, [data-testid="dashboard-grid"], .Dashboard, .react-grid-layout'
    ).forEach((el) => {
      el.style.setProperty('overflow', 'visible', 'important');
      el.style.setProperty('height', 'auto', 'important');
      el.style.setProperty('max-height', 'none', 'important');
    });

    const grid = document.querySelector('[data-testid="dashboard-grid"]');
    if (grid) grid.style.setProperty('max-width', '1500px', 'important');

    const exact = document.querySelector(
      '#Dashboard-Parameters-And-Cards-Container > div.emotion-1x2t8v2.e3g5pmu4 > div > div > div:nth-child(6)'
    );
    let how = 'none';
    if (hideEl(exact)) how = 'exact';
    else {
      const container = document.querySelector('#Dashboard-Parameters-And-Cards-Container');
      const nested = container && container.querySelector(':scope > div > div > div > div:nth-child(6)');
      if (hideEl(nested)) how = 'nested-6';
      else {
        const gridKids = grid ? [...grid.children] : [];
        if (gridKids.length >= 6 && hideEl(gridKids[5])) how = 'grid-child-6';
        else {
          const cards = [...document.querySelectorAll('[data-testid="dashcard"]')];
          const withTable = cards.filter((c) => c.querySelector('table'));
          const lastTableCard = withTable[withTable.length - 1];
          if (lastTableCard) {
            hideEl(lastTableCard.closest('.react-grid-item') || lastTableCard.parentElement || lastTableCard);
            how = 'last-table-card';
          } else if (gridKids.length && hideEl(gridKids[gridKids.length - 1])) how = 'grid-last';
        }
      }
    }

    const items = [...document.querySelectorAll('[data-testid="dashboard-grid"] .react-grid-item, [data-testid="dashcard"]')].filter(
      (el) => getComputedStyle(el).display !== 'none' && getComputedStyle(el).visibility !== 'hidden'
    );
    let maxBottom = 0;
    for (const item of items) {
      maxBottom = Math.max(maxBottom, item.offsetTop + item.offsetHeight, item.getBoundingClientRect().bottom + window.scrollY);
    }
    if (grid && maxBottom > 0) {
      const layout = grid.querySelector('.react-grid-layout') || grid;
      layout.style.setProperty('height', `${Math.ceil(maxBottom + 32)}px`, 'important');
    }
    return {
      how,
      heightPx: Math.ceil(
        Math.max(
          maxBottom + 48,
          grid ? grid.scrollHeight : 0,
          grid ? grid.offsetHeight : 0,
          document.documentElement.scrollHeight,
          document.body.scrollHeight
        )
      ),
    };
  });

  const heightPx = hidden.heightPx;
  const viewportHeight = Math.min(Math.max(Math.ceil(heightPx * 1.15) + 48, 900), 8000);
  await page.setViewport({ width: 1600, height: viewportHeight, deviceScaleFactor: 2 });
  await sleep(400);
  const heightIn = Math.min(Math.max(viewportHeight / 96 + 0.5, 12), 90);
  const pdf = await page.pdf({
    printBackground: true,
    width: '18in',
    height: `${heightIn}in`,
    margin: { top: '8px', right: '8px', bottom: '8px', left: '8px' },
    timeout: 20000,
  });
  const image = await page.screenshot({ encoding: 'base64', type: 'png' });
  return { data: { pdf: toBase64(pdf), image, hidden: hidden.how, heightPx }, type: 'application/json' };
};

